#include "std_include.h"
#include "cuda_runtime.h"
#include "vertexQuadraticEnergy.h"
#include "EnergyMinimizerFIRE2D.h"
#include "vertexTrajectoryDatabase.h"
#include <filesystem>
#include <glob.h>
#include <chrono>
#include <cstdio>
#include <sstream>
#include <vector>

// Generated by Claude Code. 2026-10-21
// Rigid quench of vertex production snapshots. Same FIRE recipe as the 2025
// KA=0 rigidity study (localTest/vertexFIRE.cpp):
//   E = sum_i KA (A_i - 1)^2 + (P_i - p0q)^2, KA = 0 by default,
//   dt = 1e-3, dtMax = 50 dt, alphaStart = 0.1, alphaDec = 0.99,
//   dtInc = 1.1, dtDec = 0.5, NMin = 5, force cutoff 1e-12, T1s on (l_T1 = 0.01).
//   Rigid if the minimized E > 1e-10 (cut of bidisperseRigidity.nb).
//   Runs in chunks of 1e4 steps and stops early once E < 1e-14 (floppy) or
//   E > 1e-6 changes by < 1e-10 relative over a chunk (rigid plateau).
// With KA = 0 every network is rigid below sqrt(8 sqrt 3) ~ 3.7224 (sum of
// areas = box, isoperimetric bound is concave in the number of sides), so
// lo = 3.70 is taken as rigid without a quench.
// Per (p0, T): last nKeep records of each idx (default 3, idx = 0..9).
// Each snapshot: quench at the production p0 ("own"), then bisect p0q on
// [lo, hi] down to tol for the onset p0*(snapshot). With -q, quench at a
// fixed list of p0q instead ("grid"). The old notebook stopped at 1e5 FIRE
// steps, so E at step 1e5 is kept next to the final E.
// One CSV row per quench under productionRuns/rigidQuench/, flushed per row.

class countingFIRE : public EnergyMinimizerFIRE
    {
    public:
        countingFIRE(shared_ptr<Simple2DModel> system, bool useGPU) : EnergyMinimizerFIRE(system,useGPU){};
        int getIterations(){return iterations;};
    };

static string findTrajectory(const string &dir, int N, double p0, double T, int idx)
    {
    char globpat[1024];
    snprintf(globpat, sizeof(globpat),
             "%sglassyDynamics_N%i_p%.4f_T%.8f_waitingTime*_idx%i.nc",
             dir.c_str(), N, p0, T, idx);
    glob_t g;
    g.gl_offs = 0;
    int rc = glob(globpat, 0, NULL, &g);
    string out;
    if (rc == 0 && g.gl_pathc > 0)
        out = g.gl_pathv[0];
    globfree(&g);
    return out;
    }

static vector<double> parseList(const string &s)
    {
    vector<double> out;
    stringstream ss(s);
    string item;
    while (getline(ss, item, ','))
        if (!item.empty())
            out.push_back(atof(item.c_str()));
    return out;
    }

static void cellSides(shared_ptr<VertexQuadraticEnergy> avm, vector<int> &z)
    {
    ArrayHandle<int> h_cvn(avm->cellVertexNum,access_location::host,access_mode::read);
    z.assign(h_cvn.data, h_cvn.data + avm->Ncells);
    }

static double hexFraction(const vector<int> &z)
    {
    int n6 = 0;
    for (int zi : z)
        if (zi == 6)
            n6 += 1;
    return (double)n6 / (double)z.size();
    }

int main(int argc, char *argv[])
    {
    int numpts = 4096;
    int USE_GPU = -1;
    double T = 0.01;
    double p0 = 3.8;
    int nKeep = 3;
    int idxLo = 0;
    int idxHi = 9;
    double KA = 0.0;
    double t1t = 0.01;
    double dt = 0.001;
    double forceCutoff = 1e-12;
    int maxIterations = 1000000;
    int chunk = 10000;
    int oldCap = 100000;
    double eRigid = 1e-10;
    double eFloppyStop = 1e-14;
    double ePlateauMin = 1e-6;
    double plateauTol = 1e-10;
    double lo = 3.70;
    double hi = 3.95;
    double tol = 0.002;
    string gridList;

    int c;
    while ((c = getopt(argc, argv, "n:g:p:v:s:i:j:k:e:r:x:c:l:u:d:q:")) != -1)
        switch (c)
            {
            case 'n': numpts = atoi(optarg); break;
            case 'g': USE_GPU = atoi(optarg); break;
            case 'p': p0 = atof(optarg); break;
            case 'v': T = atof(optarg); break;
            case 's': nKeep = atoi(optarg); break;
            case 'i': idxLo = atoi(optarg); break;
            case 'j': idxHi = atoi(optarg); break;
            case 'k': KA = atof(optarg); break;
            case 'e': dt = atof(optarg); break;
            case 'r': forceCutoff = atof(optarg); break;
            case 'x': maxIterations = atoi(optarg); break;
            case 'c': chunk = atoi(optarg); break;
            case 'l': lo = atof(optarg); break;
            case 'u': hi = atof(optarg); break;
            case 'd': tol = atof(optarg); break;
            case 'q': gridList = optarg; break;
            case '?':
                return 1;
            default:
                abort();
            };

    bool reproducible = true;
    bool initializeGPU = true;
    bool gpu = chooseGPU(USE_GPU);
    if (!gpu)
        initializeGPU = false;

    vector<double> grid = parseList(gridList);
    bool gridMode = !grid.empty();

    const char *scratchEnv = getenv("CELLGPU_SCRATCH");
    string scratch = scratchEnv ? scratchEnv : "/scratch/bbtm/cli6/glassyDynamics/data";

    char loadfolder[512];
    char savefolder[512];
    char saveDataName[768];
    snprintf(loadfolder, sizeof(loadfolder), "%s/N%i/vertex/productionRuns/p%.3f/",
             scratch.c_str(), numpts, p0);
    snprintf(savefolder, sizeof(savefolder), "%s/N%i/vertex/productionRuns/rigidQuench/",
             scratch.c_str(), numpts);
    snprintf(saveDataName, sizeof(saveDataName), "%srigidQuench_N%i_p%.4f_T%.8f_KA%.4f_idx%i-%i_%s.csv",
             savefolder, numpts, p0, T, KA, idxLo, idxHi, gridMode ? "grid" : "bisect");
    std::filesystem::create_directories(savefolder);

    cout << "p0 = " << p0 << " T = " << T << " KA = " << KA << " nKeep = " << nKeep
         << " idx = " << idxLo << ".." << idxHi << (gridMode ? " grid" : " bisect") << endl;
    cout << "FIRE dt = " << dt << " force cutoff = " << forceCutoff << " max iterations = " << maxIterations
         << " l_T1 = " << t1t << endl;
    cout << "load dir " << loadfolder << endl;
    cout << "write " << saveDataName << endl;

    FILE *out = fopen(saveDataName, "w");
    if (!out)
        {
        cout << "cannot open " << saveDataName << endl;
        return 1;
        }
    fprintf(out, "p0,T,idx,rec,time,p0q,KA,stage,E0,E1e5,E,maxF,iters,status,rigid,"
                 "q0,q,Pmean,dPrms,dPmax,p6_0,p6,nZchanged,sec\n");
    fflush(out);

    int Nvert = 2 * numpts;
    shared_ptr<VertexQuadraticEnergy> avm =
        make_shared<VertexQuadraticEnergy>(numpts, 1.0, p0, reproducible, false, initializeGPU);
    if (!initializeGPU)
        avm->setCPU();

    int nMissing = 0;
    int nShort = 0;
    int nQuench = 0;
    for (int idx = idxLo; idx <= idxHi; ++idx)
        {
        string loaddataname = findTrajectory(string(loadfolder), numpts, p0, T, idx);
        if (loaddataname.empty())
            {
            cout << "missing idx=" << idx << endl;
            nMissing += 1;
            continue;
            }
        cout << "reading " << loaddataname << endl;
        vertexTrajectoryDatabase traj(Nvert, loaddataname, NcFile::ReadOnly);
        int nrec = traj.GetNumRecs();
        if (nrec < nKeep)
            {
            cout << "records = " << nrec << " < " << nKeep << "; skip idx=" << idx << endl;
            nShort += 1;
            continue;
            }
        for (int rec = nrec - nKeep; rec < nrec; ++rec)
            {
            auto quench = [&](double p0q, const char *stage)
                {
                auto t0 = std::chrono::steady_clock::now();
                traj.readState(avm, rec, true);
                double time = avm->currentTime;
                avm->setModuliUniform(KA, 1.0);
                avm->setCellPreferencesUniform(1.0, p0q);
                avm->setT1Threshold(t1t);
                vector<int> z0, z1;
                cellSides(avm, z0);
                double E0 = avm->computeEnergy();
                double q0 = avm->reportq();

                shared_ptr<countingFIRE> fire = make_shared<countingFIRE>(avm, initializeGPU);
                if (!initializeGPU)
                    fire->setCPU();
                fire->setDeltaT(dt);
                fire->setAlphaStart(0.1);
                fire->setDeltaTMax(50 * dt);
                fire->setDeltaTInc(1.1);
                fire->setDeltaTDec(0.5);
                fire->setAlphaDec(0.99);
                fire->setNMin(5);
                fire->setForceCutoff(forceCutoff);

                double E = E0;
                double E1e5 = E0;
                double maxF = 0.0;
                string status = "maxit";
                int done = 0;
                while (done < maxIterations)
                    {
                    fire->setMaximumIterations(min(done + chunk, maxIterations));
                    fire->minimize();
                    int now = fire->getIterations();
                    double Eprev = E;
                    E = avm->computeEnergy();
                    maxF = sqrt(fire->getMaxForce());
                    if (done < oldCap && now >= oldCap)
                        E1e5 = E;
                    done = now;
                    if (E < eFloppyStop)
                        {
                        status = "floppy";
                        break;
                        }
                    if (maxF <= forceCutoff)
                        {
                        status = "conv";
                        break;
                        }
                    // rigid side: E has stopped moving well above the cut
                    if (E > ePlateauMin && fabs(Eprev - E) < plateauTol * E)
                        {
                        status = "plateau";
                        break;
                        }
                    }
                if (done < oldCap)
                    E1e5 = E;

                cellSides(avm, z1);
                int nZchanged = 0;
                for (size_t cc = 0; cc < z0.size(); ++cc)
                    if (z0[cc] != z1[cc])
                        nZchanged += 1;
                double Pmean = 0.0, dP2 = 0.0, dPmax = 0.0;
                {
                ArrayHandle<double2> h_AP(avm->returnAreaPeri(),access_location::host,access_mode::read);
                for (int cc = 0; cc < avm->Ncells; ++cc)
                    {
                    double P = h_AP.data[cc].y;
                    Pmean += P;
                    dP2 += (P - p0q) * (P - p0q);
                    dPmax = max(dPmax, fabs(P - p0q));
                    }
                }
                Pmean /= avm->Ncells;
                double dPrms = sqrt(dP2 / avm->Ncells);
                double q = avm->reportq();
                bool rigid = E > eRigid;
                double sec = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();

                fprintf(out, "%.3f,%.8f,%i,%i,%.6f,%.6f,%.4f,%s,%.10g,%.10g,%.10g,%.6g,%i,%s,%i,"
                             "%.8f,%.8f,%.8f,%.6g,%.6g,%.6f,%.6f,%i,%.2f\n",
                        p0, T, idx, rec, time, p0q, KA, stage, E0, E1e5, E, maxF, done, status.c_str(),
                        rigid ? 1 : 0, q0, q, Pmean, dPrms, dPmax, hexFraction(z0), hexFraction(z1),
                        nZchanged, sec);
                fflush(out);
                nQuench += 1;
                printf("idx %i rec %i p0q %.6f %s: E %.4g -> %.4g, maxF %.3g, %i iterations, %s, %.1f s\n",
                       idx, rec, p0q, stage, E0, E, maxF, done, rigid ? "rigid" : "floppy", sec);
                return rigid;
                };

            if (gridMode)
                {
                for (double p0q : grid)
                    quench(p0q, "grid");
                continue;
                }

            // lo is rigid, hi is floppy (hi is checked when the own quench is rigid)
            double a = lo, b = hi;
            bool rigidOwn = quench(p0, "own");
            if (rigidOwn)
                a = max(a, p0);
            else
                b = min(b, p0);
            if (rigidOwn && quench(b, "hi"))
                continue;
            while (b - a > tol)
                {
                double mid = 0.5 * (a + b);
                if (quench(mid, "bisect"))
                    a = mid;
                else
                    b = mid;
                }
            printf("idx %i rec %i: p0* in [%.5f, %.5f]\n", idx, rec, a, b);
            }
        }

    fclose(out);
    cout << "n_quench = " << nQuench << " n_missing = " << nMissing << " n_short = " << nShort << endl;
    if (initializeGPU)
        cudaDeviceReset();
    return nQuench > 0 ? 0 : 1;
    }
